CREATE OR REPLACE TRIGGER trg_dept_limit
  AFTER INSERT OR UPDATE OF dept_id ON employees
  FOR EACH ROW
DECLARE
  v_count NUMBER;
BEGIN
  SELECT COUNT(*)
    INTO v_count
    FROM employees
   WHERE dept_id = :NEW.dept_id;

  IF v_count > 3 THEN
    RAISE_APPLICATION_ERROR(-20001,
      'Department ' || :NEW.dept_id || ' would have ' || v_count || ' employees (max 3)');
  END IF;
END;
/

DROP TRIGGER trg_dept_limit;

CREATE OR REPLACE TRIGGER trg_dept_limit
  FOR INSERT OR UPDATE OF dept_id ON employees
  COMPOUND TRIGGER

  -- Set of department ids touched by this statement
  TYPE t_dept_set IS TABLE OF BOOLEAN INDEX BY PLS_INTEGER;
  g_depts   t_dept_set;
  v_dept    PLS_INTEGER;
  v_count   PLS_INTEGER;

  AFTER EACH ROW IS
  BEGIN
    g_depts(:NEW.dept_id) := TRUE;   -- no query here
  END AFTER EACH ROW;

  AFTER STATEMENT IS
  BEGIN
    v_dept := g_depts.FIRST;
    WHILE v_dept IS NOT NULL LOOP
      SELECT COUNT(*)
        INTO v_count
        FROM employees
       WHERE dept_id = v_dept;

      IF v_count > 3 THEN
        RAISE_APPLICATION_ERROR(-20001,
          'Department ' || v_dept || ' would have ' || v_count || ' employees (max 3)');
      END IF;

      v_dept := g_depts.NEXT(v_dept);
    END LOOP;
  END AFTER STATEMENT;

END trg_dept_limit;
/

CREATE OR REPLACE TRIGGER trg_dept_limit
  AFTER INSERT OR UPDATE OF dept_id ON employees
  FOR EACH ROW
DECLARE
  PRAGMA AUTONOMOUS_TRANSACTION;   -- do not do this
  v_count NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_count
    FROM employees
   WHERE dept_id = :NEW.dept_id;

  IF v_count > 3 THEN
    RAISE_APPLICATION_ERROR(-20001, 'Department full');
  END IF;
END;
/

